-- Read-only object/RLS/privilege evidence; no data, secret values or function bodies.
with expected_functions(schema_name,name) as (values ('private','campus_community_active'),('private','campus_community_blocked'),('private','campus_community_flow_mutate'),('private','campus_community_mutate'),('private','campus_community_read_comment'),('private','campus_community_read_post'),('private','campus_community_reward_state'),('private','campus_community_scope'),('private','campus_community_url'),('private','campus_exchange_read'),('private','campus_office_connection'),('private','campus_office_ingest'),('private','campus_office_mutate'),('private','campus_office_scope'),('private','campus_portfolio_file_complete'),('private','campus_portfolio_file_prepare'),('private','campus_portfolio_file_read'),('private','campus_portfolio_file_share'),('private','campus_portfolio_revoke_share'),('public','edu_campus_archive_available'),('public','edu_campus_archive_read'),('public','edu_campus_archive_write'),('public','edu_campus_business_case_command'),('public','edu_campus_business_guard'),('public','edu_campus_business_has_scope'),('public','edu_campus_business_learning_cases'),('public','edu_campus_business_payload_valid'),('public','edu_campus_business_review_available'),('public','edu_campus_business_review_guard'),('public','edu_campus_business_review_read'),('public','edu_campus_business_review_respond'),('public','edu_campus_community_flow_mutate'),('public','edu_campus_community_mutate'),('public','edu_campus_community_operator'),('public','edu_campus_community_rewards'),('public','edu_campus_create_study'),('public','edu_campus_focus_guard'),('public','edu_campus_focus_has_scope'),('public','edu_campus_observe_space_http'),('public','edu_campus_office_connection'),('public','edu_campus_office_ingest'),('public','edu_campus_office_mutate'),('public','edu_campus_office_queue'),('public','edu_campus_portfolio_file_complete'),('public','edu_campus_portfolio_file_prepare'),('public','edu_campus_portfolio_file_share'),('public','edu_campus_reserve_office'),('public','edu_campus_space_chat_guard'),('public','edu_campus_space_claim_seat'),('public','edu_campus_space_member'),('public','edu_campus_space_open'),('public','edu_campus_space_presence_guard'),('public','edu_campus_space_prune'),('public','edu_campus_space_seat_guard'),('public','edu_campus_space_topic'),('public','edu_campus_space_zone_open'),('public','edu_campus_support_created_clock'),('public','edu_campus_support_followup'),('public','edu_campus_support_scope')), expected_tables(schema_name,name) as (values ('private','edu_campus_community_flow_receipts'),('private','edu_campus_community_receipts'),('private','edu_campus_office_connectors'),('private','edu_campus_office_events'),('private','edu_campus_office_receipts'),('public','edu_campus_archive_commands'),('public','edu_campus_archive_entries'),('public','edu_campus_blocks'),('public','edu_campus_business_case_events'),('public','edu_campus_business_cases'),('public','edu_campus_business_records'),('public','edu_campus_business_review_links'),('public','edu_campus_business_review_replies'),('public','edu_campus_comments'),('public','edu_campus_community_flow_history'),('public','edu_campus_demo_questions'),('public','edu_campus_demo_slots'),('public','edu_campus_exchanges'),('public','edu_campus_feedback_acknowledgments'),('public','edu_campus_focus_sessions'),('public','edu_campus_launches'),('public','edu_campus_moderation_log'),('public','edu_campus_office_bookings'),('public','edu_campus_office_history'),('public','edu_campus_office_jobs'),('public','edu_campus_office_sessions'),('public','edu_campus_portfolio_file_access_log'),('public','edu_campus_portfolio_files'),('public','edu_campus_post_revisions'),('public','edu_campus_posts'),('public','edu_campus_preferences'),('public','edu_campus_reports'),('public','edu_campus_review_windows'),('public','edu_campus_reward_rules'),('public','edu_campus_space_chat'),('public','edu_campus_space_controls'),('public','edu_campus_space_http_metrics'),('public','edu_campus_space_presence'),('public','edu_campus_space_profiles'),('public','edu_campus_space_seats'),('public','edu_campus_support_actions'),('public','edu_campus_support_requests')), f as (
 select e.*,p.oid is not null as present,pg_get_function_identity_arguments(p.oid) as identity_arguments,p.prosecdef as security_definer,
 case when p.oid is not null then has_function_privilege('anon',p.oid,'execute') end anon_execute,
 case when p.oid is not null then has_function_privilege('authenticated',p.oid,'execute') end authenticated_execute,
 case when p.oid is not null then has_function_privilege('service_role',p.oid,'execute') end service_execute
 from expected_functions e left join pg_namespace n on n.nspname=e.schema_name left join pg_proc p on p.pronamespace=n.oid and p.proname=e.name
), t as (
 select e.*,c.oid is not null as present,c.relrowsecurity as rls_enabled,c.relacl::text as acl,
 (select count(*) from pg_policy p where p.polrelid=c.oid) as policy_count
 from expected_tables e left join pg_namespace n on n.nspname=e.schema_name left join pg_class c on c.relnamespace=n.oid and c.relname=e.name
)
select jsonb_build_object('functions',(select jsonb_agg(to_jsonb(f) order by schema_name,name,identity_arguments) from f),
 'tables',(select jsonb_agg(to_jsonb(t) order by schema_name,name) from t),
 'portfolioBucket',(select jsonb_agg(jsonb_build_object('id',id,'public',public,'file_size_limit',file_size_limit,'allowed_mime_types',allowed_mime_types)) from storage.buckets where id='campus-portfolio-private'),
 'sharedCampusPolicies',(select jsonb_agg(jsonb_build_object('schema',schemaname,'table',tablename,'policy',policyname,'roles',roles,'command',cmd,'permissive',permissive)) from pg_policies where schemaname in ('storage','realtime') and policyname like '%campus%')
) as metadata;
